import datetime as _rdt

def _r_list(items): return '<ul class="dg-list">' + "".join(f"<li>{x}</li>" for x in items) + "</ul>"
def _r_steps(items): return '<ol class="steps">' + "".join(f"<li>{x}</li>" for x in items) + "</ol>"
def _r_table(head, rows):
    th = "".join(f"<th>{e(h)}</th>" for h in head)
    tr = "".join("<tr>" + "".join(f"<td>{c}</td>" for c in r) + "</tr>" for r in rows)
    return f'<div class="tbl"><table class="ptable"><thead><tr>{th}</tr></thead><tbody>{tr}</tbody></table></div>'

# Dhanteras 2026 buying choghadiya for Delhi, computed with the site's own choghadiya code
_DT_DAY = _rdt.date(2026, 11, 6)
_dl = next(c for c in IN_CITIES if c[1] == "Delhi")
_ch = chogh(_dl[2], _dl[3], _DT_DAY)
_good_day = [x for x in _ch["day"] if CH_KIND[x[0]][0] == "good"]
_good_night = [x for x in _ch["night"][:4] if CH_KIND[x[0]][0] == "good"]
_best = ", ".join(f"{n} ({ct12(a)} – {ct12(b)})" for n, a, b in _good_day)

