import re as _rre
def _r_name(r):
    m = _rre.search(r"<title>([^<]+)</title>", PAGES.get(r, ""))
    return _rre.split(r" — | \| | – |: ", m.group(1))[0].strip() if m else r

for g in ROADMAP_PAGES:
    secs = "".join('<h2 class="k-h">' + e(h) + "</h2>" + b for h, b in g["sections"])
    secs += f'<p class="pc-note">जानकारी की जाँच: 27 अक्टूबर 2026। ये परंपराएँ और मान्यताएँ हैं; अपने परिवार की रीति को प्राथमिकता दें।</p>'
    rel = [r for r in g["rel"] if r in PAGES or any(r == x["slug"] for x in ROADMAP_PAGES)]
    read = '<ul class="library">' + "".join(f'<li><a href="{r}"><strong>{e(_r_name(r) if r in PAGES else next(x["crumb"] for x in ROADMAP_PAGES if x["slug"] == r))}</strong><span>साथ में पढ़ें</span></a></li>' for r in rel) + "</ul>"
    body = (band(g["h1"], g["answer"], g["crumb"]) +
            '<article><section><div class="wrap prose katha">' + secs + "</div></section></article>" +
            '<section class="no-print"><div class="wrap">' + sec_head("साथ में पढ़ें") + read + "</div></section>" + faq_html(g["faqs"]))
    ld = [{"@type": "Article", "headline": g["h1"], "inLanguage": "hi", "author": {"@id": SITE + "#organization"},
           "publisher": {"@id": SITE + "#organization"}, "dateModified": TODAY, "description": g["desc"]}, faq_ld(g["faqs"])]
    add(g["slug"], g["title"], g["desc"], body, crumbs=g["crumb"], ld=ld, active="tyohar-calendar.html")

# link the new pages from their festival's "kab hai" page (above its FAQ)
_by_parent = {}
for g in ROADMAP_PAGES: _by_parent.setdefault(g["parent"], []).append(g)
for p, gs in _by_parent.items():
    if p in PAGES:
        row = ('<section class="band no-print"><div class="wrap">' + sec_head("और जानकारी") + '<ul class="library">' +
               "".join(f'<li><a href="{g["slug"]}"><strong>{e(g["crumb"])}</strong><span>पूरी जानकारी</span></a></li>' for g in gs) + "</ul></div></section>")
        PAGES[p] = PAGES[p].replace('<section class="faq">', row + '<section class="faq">', 1)
